// ─── Client Class ────────────────────────────────────────────────────

/**
 * Unified HTTP client for the my-pizza-team daemon.
 *
 * Constructor takes the daemon URL, an agent ID (unique per Pi instance), and
 * options: an auth token (reserved for future multi-user auth) and this
 * integration's build version (reported in the registration handshake).
 *
 * Deliberately free of dependencies: no npm packages, no node: builtins, and one
 * relative import — the import-free ../shared/agent-protocol.ts, by its
 * `.ts` name — beside `fetch`. That is what lets it load standalone under Node's
 * type stripping, which in turn is what makes it testable
 * (tests/runtime-purity.test.ts).
 */
export class DaemonClient {
  private baseUrl: string;
  private agentId: string;
  private authToken: string | undefined;

  /** This integration's own build version, reported at registration. */
  private harnessVersion: string | undefined;
  /** Which harness this agent runs under, reported at registration ("pi" unless told). */
  private harness: string;

  constructor(
    daemonUrl: string,
    agentId: string,
    options?: { authToken?: string; harnessVersion?: string; harness?: string },
  ) {
    this.baseUrl = daemonUrl.replace(/\/$/, "");
    this.agentId = agentId;
    this.authToken = options?.authToken;
    this.harnessVersion = options?.harnessVersion;
    this.harness = options?.harness ?? "pi";
  }

  /** The agent's unique ID */
  get id(): string {
    return this.agentId;
  }

  /** The daemon's base URL */
  get url(): string {
    return this.baseUrl;
  }

  // ─── Internal Helpers ────────────────────────────────────────────

  /**
   * Make a fetch request with standard headers. Throws DaemonError on
   * non-2xx responses with the error message from the response body.
   */
  private async request(path: string, options?: RequestInit): Promise<Response> {
    const headers: Record<string, string> = {
      ...(options?.headers as Record<string, string> || {}),
    };
    if (this.authToken) {
      headers["Authorization"] = `Bearer ${this.authToken}`;
    }
    if (options?.body && !headers["Content-Type"]) {
      headers["Content-Type"] = "application/json";
    }

    const res = await fetch(`${this.baseUrl}${path}`, {
      ...options,
      headers,
    });

    if (!res.ok) {
      let errorMsg = `HTTP ${res.status}`;
      let feature: FeatureName | undefined;
      let code: string | undefined;
      try {
        const body = await res.json() as any;
        if (body.error) errorMsg = body.error;
        if (typeof body.code === "string") code = body.code;
        // A feature-toggle refusal: replace the terse "feature 'x' is disabled"
        // with the actionable wording, so a tool error tells the model (and the
        // user) how to turn the kind back on.
        if (res.status === 403 && (FEATURE_NAMES as readonly string[]).includes(body.feature)) {
          feature = body.feature as FeatureName;
          errorMsg = featureDisabledMessage(feature);
        }
      } catch {
        // If body isn't JSON, use status text
        errorMsg = res.statusText || errorMsg;
      }
      throw new DaemonError(errorMsg, res.status, feature, code);
    }

    return res;
  }

  /** POST with JSON body, returns parsed JSON */
  private async post<T>(path: string, body: Record<string, any>): Promise<T> {
    const res = await this.request(path, {
      method: "POST",
      body: JSON.stringify(body),
    });
    return res.json() as Promise<T>;
  }

  /** GET, returns parsed JSON */
  private async get<T>(path: string): Promise<T> {
    const res = await this.request(path);
    return res.json() as Promise<T>;
  }

  /** PUT with JSON body, returns parsed JSON */
  private async put<T>(path: string, body: Record<string, any>): Promise<T> {
    const res = await this.request(path, {
      method: "PUT",
      body: JSON.stringify(body),
    });
    return res.json() as Promise<T>;
  }

  /** PATCH with JSON body, returns parsed JSON (partial updates, e.g. thoughts) */
  private async patch<T>(path: string, body: Record<string, any>): Promise<T> {
    const res = await this.request(path, {
      method: "PATCH",
      body: JSON.stringify(body),
    });
    return res.json() as Promise<T>;
  }

  /** DELETE, returns parsed JSON */
  private async delete<T>(path: string): Promise<T> {
    const res = await this.request(path, { method: "DELETE" });
    return res.json() as Promise<T>;
  }

  // ═══════════════════════════════════════════════════════════════════
  // HEALTH
  // ═══════════════════════════════════════════════════════════════════

  /**
   * Check if the daemon is reachable.
   * Returns true if GET /health responds with 2xx, false otherwise.
   * Never throws — safe for polling loops.
   */
  async checkHealth(): Promise<boolean> {
    try {
      const res = await fetch(`${this.baseUrl}/health`);
      return res.ok;
    } catch {
      return false;
    }
  }

  /**
   */
  async getStatus(): Promise<StatusResponse> {
    return this.get<StatusResponse>("/api/status");
  }

  // ═══════════════════════════════════════════════════════════════════
  // AGENT PROTOCOL
  // ═══════════════════════════════════════════════════════════════════

  /**
   * Register this agent with the daemon.
   *
   * Called once at startup. Provides the agent's name and working directory
   * (which drives directory-affinity matching), plus the version handshake.
   *
   * Returns workflow config and host-specific settings. A leader refused because
   * another leader is live throws a DaemonError with `code`
   * `LEADER_ALREADY_CONNECTED` (`isLeaderAlreadyConnected`).
   */
  async register(opts: {
    name: string;
    /** The agent's working directory (its pi cwd). Drives directory-affinity matching. */
    directory?: string;
    /** Opaque harness metadata (e.g. tmux window) the daemon stores + relays back. */
    metadata?: Record<string, unknown>;
  }): Promise<AgentRegisterResponse> {
    return this.post<AgentRegisterResponse>("/api/agents/register", {
      id: this.agentId,
      name: opts.name,
      directory: opts.directory,
      metadata: opts.metadata,
      // Version handshake: the daemon gates on protocolVersion and reports the
      // rest for the UI's skew banner.
      protocolVersion: PROTOCOL_VERSION,
      harness: this.harness,
      harnessVersion: this.harnessVersion,
      // Per-process, so a reconnect of this process is accepted where another
      // process registering as the same live leader is refused.
      instanceId: processInstanceId(),
    });
  }

  /**
   * Deregister this agent from the daemon.
   *
   * Called on clean shutdown. Releases any task assignments and removes
   * the agent from the team. The daemon also auto-reaps agents that
   * stop sending heartbeats.
   */
  async deregister(): Promise<{ success: boolean }> {
    return this.delete<{ success: boolean }>(`/api/agents/${encodeURIComponent(this.agentId)}`);
  }

  /** The team's registered agents (id, name, status), as the Team tab sees them. */
  async listAgents(): Promise<{ agents: Array<{ id: string; name: string; status: string }> }> {
    return this.get<{ agents: Array<{ id: string; name: string; status: string }> }>("/api/agents");
  }

  /**
   * Dismiss another agent, as the UI's dismiss button does: the daemon tombstones it
   * (its next heartbeat tells it to exit) and closes its tmux window once it has.
   */
  async dismissAgent(agentId: string): Promise<{ success: boolean }> {
    return this.delete<{ success: boolean }>(`/api/agents/${encodeURIComponent(agentId)}?dismiss=true`);
  }

  /**
   * Bring another agent's tmux window to the front (the leader's /ppt-hop). The
   * daemon selects the window — a harness never runs tmux itself (docs/DESIGN.md
   * "The Daemon Is the Supervisor"). Throws a DaemonError with the reason when it
   * can't (unknown agent, no such window, tmux unreachable).
   */
  async focusAgent(agentId: string): Promise<{ success: boolean }> {
    return this.post<{ success: boolean }>(`/api/agents/${encodeURIComponent(agentId)}/focus`, {});
  }

  /**
   * Send a heartbeat to the daemon.
   *
   * Called periodically (e.g., every 30s) to confirm the agent is alive.
   * If heartbeats stop, the daemon considers the agent offline and may
   * release its assigned tasks.
   *
   * Never throws — safe for background intervals.
   */
  async heartbeat(status: "idle" | "working" | "pairing", currentTask?: string): Promise<{ dismissed?: boolean; reregister?: boolean }> {
    try {
      const res = await this.post<{ success: boolean; dismissed?: boolean; reregister?: boolean }>("/api/agents/heartbeat", {
        id: this.agentId,
        status,
        currentTask,
      });
      return { dismissed: res.dismissed, reregister: res.reregister };
    } catch {
      // Heartbeat failures are non-fatal — daemon may be temporarily unreachable
      return {};
    }
  }

  /**
   * Poll for available work. Returns the next `READY` WorkItem the daemon
   * matches to this agent (directory affinity), or `{ workItem: null }` when
   * none is available or distribution is paused.
   */
  async getNextWork(): Promise<AgentNextWorkResponse> {
    return this.get<AgentNextWorkResponse>(
      `/api/agents/next-work?agentId=${encodeURIComponent(this.agentId)}`
    );
  }

  /**
   * Claim (lease) a READY WorkItem (→ IN_PROGRESS). Returns the daemon-assembled
   * prompt (state persona + story/task context, or the WorkDef's goal) to
   * deliver verbatim.
   */
  async claimWorkItem(workItemId: string): Promise<AgentClaimResponse> {
    return this.post<AgentClaimResponse>(
      `/api/agents/claim/${encodeURIComponent(workItemId)}`,
      { agentId: this.agentId }
    );
  }

  /**
   * Set the WorkItem's terminal state (the single state-setter). `COMPLETE`
   * advances a task ref to its next workflow state (teammates never move tasks);
   * `FAILED` leaves the task stuck for a human. "Giving up" is a comment plus a
   * FAILED here — the daemon bundles nothing.
   */
  async setWorkItemState(workItemId: string, state: "COMPLETE" | "FAILED"): Promise<AgentSetWorkItemStateResponse> {
    return this.post<AgentSetWorkItemStateResponse>(
      `/api/agents/work-items/${encodeURIComponent(workItemId)}/state`,
      { agentId: this.agentId, state }
    );
  }

  /**
   * Fail a WorkItem because the agent's *session errored* (the model call
   * failed), not because the agent gave up. The daemon retries it with backoff
   * and posts the attempt's `[retry]`/`[failed]` comment itself, so the caller
   * posts nothing (my-pizza-team docs/DESIGN.md "Errored Sessions Retry").
   */
  async failWorkItemForSessionError(workItemId: string, sessionError: string): Promise<AgentSetWorkItemStateResponse> {
    return this.post<AgentSetWorkItemStateResponse>(
      `/api/agents/work-items/${encodeURIComponent(workItemId)}/state`,
      { agentId: this.agentId, state: "FAILED", sessionError }
    );
  }

  /**
   * End a poll state's check with "not yet" (`WAITED`): the task stays in its
   * state and the daemon runs the next check later (my-pizza-team
   * docs/DESIGN.md "Polling States"). Only accepted when the claim said
   * `completion: "poll"`; the caller posts its own comment first.
   */
  async waitWorkItem(workItemId: string, reason: string): Promise<AgentSetWorkItemStateResponse> {
    return this.post<AgentSetWorkItemStateResponse>(
      `/api/agents/work-items/${encodeURIComponent(workItemId)}/state`,
      { agentId: this.agentId, state: "WAITED", reason }
    );
  }

  // ═══════════════════════════════════════════════════════════════════
  // COMMENTS (replaces old "messages")
  // ═══════════════════════════════════════════════════════════════════

  /**
   * A WorkItem's current state. Used to tell whether an item this agent holds was
   * already failed some other way (e.g. `mpt agent fail`) before completing it.
   */
  async getWorkItemState(workItemId: string): Promise<string | null> {
    const res = await this.get<{ item?: { state?: string } }>(`/api/work-items/${encodeURIComponent(workItemId)}`);
    return res.item?.state ?? null;
  }

  /** Post a comment on a WorkItem's ref (task or WorkDef). */
  async postComment(workItemId: string, body: string, attachments?: Array<{ name: string; size: number; type: string }>): Promise<{ success: boolean }> {
    return this.post<{ success: boolean }>(
      `/api/agents/comments/${encodeURIComponent(workItemId)}`,
      { agentId: this.agentId, body, attachments }
    );
  }

  // ═══════════════════════════════════════════════════════════════════
  // TOKEN USAGE
  // ═══════════════════════════════════════════════════════════════════

  /**
   * Report one agent run's usage to the daemon's ledger (any kind of run).
   * `workItemId` attaches it to that item's WorkDef (per-task cost rollups).
   */
  async reportUsage(usage: {
    inputTokens: number;
    outputTokens: number;
    cacheReadTokens: number;
    cacheWriteTokens: number;
    model: string;
    costUsd: number;
    kind: "work" | "pairing" | "chat" | "other";
    workItemId?: string;
  }): Promise<{ success: boolean }> {
    return this.post<{ success: boolean }>(`/api/agents/${encodeURIComponent(this.agentId)}/usage`, usage);
  }

  /**
   * Post a triage analysis: prose, an outcome, and the work it proposes
   * (my-pizza-team docs/DESIGN.md "Auto Triage"). Only valid while holding a
   * triage work item; the daemon validates and returns a fixable error.
   */
  async proposeWork(workItemId: string, analysis: {
    body: string;
    outcome: "proposals" | "nothing" | "question";
    proposals?: unknown[];
  }): Promise<{ success: boolean; error?: string }> {
    return this.post<{ success: boolean; error?: string }>(
      `/api/agents/work-items/${encodeURIComponent(workItemId)}/proposals`,
      { agentId: this.agentId, ...analysis },
    );
  }

  /**
   * Report this session's model, context-window fill, and cost, for the Team tab
   * (see runtime/session-stats.ts). Never throws — it's display-only, and an
   * older daemon without the route just ignores it.
   */
  async reportSessionStats(stats: {
    contextTokens: number | null;
    contextWindow: number | null;
    contextPercent: number | null;
    costUsd: number;
    model: { id: string; name: string; provider: string } | null;
  }): Promise<void> {
    try {
      await this.post<{ success: boolean }>(`/api/agents/${encodeURIComponent(this.agentId)}/session-stats`, stats);
    } catch { /* display-only */ }
  }

  // ═══════════════════════════════════════════════════════════════════
  // ATTACHMENTS
  // ═══════════════════════════════════════════════════════════════════

  /**
   * Upload a file attachment to a task.
   *
   * Stores the file in the task's attachments directory. The daemon
   * auto-detects the file type (diff, markdown, json, etc.).
   */
  async uploadAttachment(workItemId: string, filename: string, content: string): Promise<UploadAttachmentResponse> {
    return this.post<UploadAttachmentResponse>(
      `/api/agents/work-items/${encodeURIComponent(workItemId)}/attachments`,
      { name: filename, content, encoding: "utf-8" }
    );
  }

  // ═══════════════════════════════════════════════════════════════════
  // SPAWN REQUESTS (leader only)
  // ═══════════════════════════════════════════════════════════════════

  /**
   * Pending leader directives the daemon hands out. Since the daemon realizes
   * `spawn` and `dismiss` itself and resets go to the agent, a current leader has
   * nothing to poll here; kept for the protocol's sake.
   */
  async getLeaderDirectives(): Promise<LeaderDirectivesResponse> {
    return this.get<LeaderDirectivesResponse>("/api/leader/directives");
  }

  /**
   * Create a leader directive (e.g. a `spawn`). For `spawn` the daemon generates a
   * unique agent name into the returned directive's params.
   */
  async createLeaderDirective(action: string, opts?: { memberId?: string; params?: Record<string, unknown> }): Promise<CreateLeaderDirectiveResponse> {
    return this.post<CreateLeaderDirectiveResponse>(
      "/api/leader/directives",
      { action, memberId: opts?.memberId, params: opts?.params }
    );
  }

  /**
   * Spawn requests the daemon hasn't realized yet, and the ones it failed (with
   * the reason), so a caller that asked for a spawn can tell how it went.
   */
  async getSpawnRequests(): Promise<{
    requests: Array<{ id: string; name: string | null; cwd: string | null; createdAt: string }>;
    failed: Array<{ id: string; name: string | null; cwd: string | null; error: string | null; at: string }>;
  }> {
    return this.get("/api/spawn-requests");
  }

  /** Mark a directive complete once the leader has realized it. */
  async completeLeaderDirective(id: string): Promise<{ success: boolean }> {
    return this.put<{ success: boolean }>(
      `/api/leader/directives/${encodeURIComponent(id)}`,
      { status: "done" }
    );
  }

  /**
   * Mark a directive failed when it can't be realized (e.g. an invalid spawn
   * cwd). This removes it from the pending queue so the leader stops retrying
   * an ask that will never succeed — the alternative is an infinite retry loop.
   */
  async failLeaderDirective(id: string): Promise<{ success: boolean }> {
    return this.put<{ success: boolean }>(
      `/api/leader/directives/${encodeURIComponent(id)}`,
      { status: "failed" }
    );
  }

  // ═══════════════════════════════════════════════════════════════════
  // ASSISTANT CHAT (mirror between the daemon chat and this Pi session)
  // ═══════════════════════════════════════════════════════════════════
  //
  // Chat v2 has no turns: the daemon queues the user's messages, this agent
  // pulls them and hands them to Pi, and the agent's own prose is mirrored back
  // as bubbles. See my-pizza-team/docs/DESIGN.md "Assistant Chat Model".

  /**
   * User messages not yet handed to Pi, oldest first, plus whether we are the
   * designated chat agent. The daemon designates one leader so a multi-host team
   * can't answer the same message twice.
   */
  async getInbox(): Promise<AssistantInboxResponse> {
    return this.get<AssistantInboxResponse>(
      `/api/assistant/inbox?agentId=${encodeURIComponent(this.agentId)}`,
    );
  }

  /**
   * Advance delivery receipts. `delivered` = handed to Pi; `read` = a run that
   * sees them has started. Calling with no ids and `read` promotes everything
   * already delivered (what we do on agent_start).
   */
  async ackInbox(ids: string[], state: AssistantDelivery): Promise<AssistantMirrorResponse> {
    return this.post<AssistantMirrorResponse>("/api/assistant/inbox/ack", { ids, state });
  }

  /** Mirror one bubble (one paragraph of the agent's reply) into the chat. */
  async postBubble(content: string, failed = false): Promise<AssistantMirrorResponse> {
    return this.post<AssistantMirrorResponse>("/api/assistant/bubbles", { content, failed });
  }

  /**
   * Update the ephemeral reasoning peek: append a `chunk`, `clear` the buffer at
   * the start of a run, and/or toggle the `thinking` (…) indicator.
   */
  async postThought(body: { chunk?: string; clear?: boolean; thinking?: boolean }): Promise<AssistantMirrorResponse> {
    return this.post<AssistantMirrorResponse>("/api/assistant/thoughts", body);
  }

  /** Report the Pi session file backing the chat, so the user can resume it later. */
  async reportPiSession(piSessionPath: string): Promise<AssistantMirrorResponse> {
    return this.post<AssistantMirrorResponse>("/api/assistant/session", { piSessionPath });
  }

  /**
   * Mirror a message the user typed in this agent's terminal into the web chat,
   * so both surfaces show the same conversation.
   */
  async mirrorUserMessage(content: string): Promise<AssistantMirrorResponse> {
    return this.post<AssistantMirrorResponse>("/api/assistant/messages", { content, origin: "tui" });
  }

  /** Directives this agent must realize itself (session replacement). */
  async getSelfDirectives(): Promise<{ directives: LeaderDirective[] }> {
    return this.get<{ directives: LeaderDirective[] }>(
      `/api/agents/${encodeURIComponent(this.agentId)}/directives`,
    );
  }

  // ─── Web pairing (my-pizza-team docs/DESIGN.md "Watching and Pairing with a Teammate") ────────────

  /**
   * Poll this teammate's web-pairing intent. Drains: queued messages and a
   * pending release are returned exactly once.
   */
  async getPairing(): Promise<PairingPoll> {
    return this.get<PairingPoll>(`/api/agents/${encodeURIComponent(this.agentId)}/pairing`);
  }

  // ─── Teammate transcript (watch view; my-pizza-team docs/DESIGN.md "Watching and Pairing with a Teammate") ─

  /**
   * Is anyone watching this agent's live transcript? Mirror only while true.
   * `backfill` says the daemon accepts a backfill batch (older daemons omit it).
   */
  async getTranscriptWatch(): Promise<TranscriptWatchResponse> {
    const res = await this.get<TranscriptWatchResponse>(
      `/api/agents/${encodeURIComponent(this.agentId)}/transcript/watch`,
    );
    return { watched: !!res.watched, backfill: res.backfill === true };
  }

  /**
   * Post a batch of transcript entries. The response says whether the agent is
   * still watched, so the mirror can stop as soon as the viewer's grace runs out.
   * With `backfill`, the batch is the session so far and replaces the daemon's
   * buffer (send it only to a daemon whose watch poll said `backfill: true`).
   */
  async postTranscript(entries: Record<string, unknown>[], backfill?: TranscriptBackfill): Promise<{ watched: boolean }> {
    const res = await this.post<{ watched: boolean }>(
      `/api/agents/${encodeURIComponent(this.agentId)}/transcript`,
      backfill ? { entries, backfill } : { entries },
    );
    return { watched: !!res.watched };
  }

  /** Mark a self-directive done (or failed). */
  async completeSelfDirective(id: string, status = "done"): Promise<AssistantMirrorResponse> {
    return this.put<AssistantMirrorResponse>(
      `/api/agents/${encodeURIComponent(this.agentId)}/directives/${encodeURIComponent(id)}`,
      { status },
    );
  }

  /**
   * Get the assistant's active persona and the effective system prompt to
   * inject. When no persona is selected the daemon returns its default
   * assistant persona in `systemPrompt`, so this is never empty in practice.
   */
  async getPersona(): Promise<{ personaId: string | null; entry: PersonaSummary | null; persona?: PersonaSummary; systemPrompt: string }> {
    return this.get("/api/assistant/persona");
  }

  /**
   * Read the user's Thoughts board (markdown sticky notes) + groups. Read-only:
   * the assistant reads notes — often by group — to help turn them into work
   * (a story/task/schedule). Optional status filter (active|archived).
   */
  async listThoughts(status?: string): Promise<{ thoughts: Thought[]; groups: ThoughtGroup[] }> {
    const q = status ? `?status=${encodeURIComponent(status)}` : "";
    return this.get(`/api/thoughts${q}`);
  }

  /** Read a single thought by id. */
  async getThought(id: string): Promise<{ success: boolean; thought?: Thought; error?: string }> {
    return this.get(`/api/thoughts/${encodeURIComponent(id)}`);
  }

  /**
   * Create a standalone WorkDef. Solitary by default (enqueued immediately so it
   * lands in the Inbox when done); pass `type: "Scheduled"` + `cron` to create a
   * recurring job instead. This is how the assistant turns thoughts into work.
   * `pending: true` saves it for review instead: never enqueued until activated.
   */
  async createWorkDef(body: {
    title: string; goal: string; acceptanceCriteria?: string; additionalContext?: string;
    directory?: string; type?: "Solitary" | "Scheduled"; cron?: string; enqueue?: boolean;
    pending?: boolean; persona?: string;
  }): Promise<{ success: boolean; workDef?: { id: string; title: string }; error?: string }> {
    return this.post("/api/work-defs", body);
  }

  /** Read any WorkDef (board task, Solitary, Scheduled) by id, including its `pending` flag. */
  async getWorkDef(id: string): Promise<{ workDef?: WorkDefSummary; success?: boolean; error?: string }> {
    return this.get(`/api/work-defs/${encodeURIComponent(id)}`);
  }

  /**
   * Edit a WorkDef's definition. The daemon only accepts this while the WorkDef
   * is pending; once active it answers 409 (thrown as a DaemonError), since an
   * active definition is locked — revise it with a comment and a re-run.
   */
  async updateWorkDef(id: string, updates: {
    title?: string; goal?: string; acceptanceCriteria?: string; additionalContext?: string | null;
    directory?: string | null; persona?: string | null;
  }): Promise<{ success: boolean; workDef?: WorkDefSummary; error?: string }> {
    return this.put(`/api/work-defs/${encodeURIComponent(id)}`, updates);
  }

  /**
   * Activate a pending WorkDef: locks its definition and lets the daemon enqueue it
   * (Solitary now, a board task when its story admits it, Scheduled on its cron).
   */
  async activateWorkDef(id: string): Promise<{ success: boolean; workDef?: WorkDefSummary; workItemId?: string | null; error?: string }> {
    return this.post(`/api/work-defs/${encodeURIComponent(id)}/activate`, {});
  }

  /**
   * Make a Schedule pending (its cron stops firing) or active again (it resumes
   * at its next cron occurrence; skipped runs are not back-filled). Reversible,
   * unlike a WorkDef's pending. Takes the Schedule id (a Scheduled WorkDef's
   * `parent.id`).
   */
  async setSchedulePending(scheduleId: string, pending: boolean): Promise<{ success: boolean; schedule?: { id: string; cron: string; pending: boolean }; error?: string }> {
    return this.post(`/api/schedules/${encodeURIComponent(scheduleId)}/${pending ? "pending" : "activate"}`, {});
  }

  // ─── Thoughts: write (the assistant refines the board) ─────────────────

  /** Create a sticky note. `createdBy` attributes it (e.g. "assistant"). */
  async createThought(body: { content?: string; color?: string; groupId?: string; pinned?: boolean; createdBy?: string }): Promise<{ success: boolean; thought?: Thought; error?: string }> {
    return this.post("/api/thoughts", body);
  }

  /** Update a note (partial). `groupId: null` removes it from its group. */
  async updateThought(id: string, updates: { content?: string; color?: string; pinned?: boolean; groupId?: string | null; status?: "active" | "archived" }): Promise<{ success: boolean; thought?: Thought; error?: string }> {
    return this.patch(`/api/thoughts/${encodeURIComponent(id)}`, updates);
  }

  /** Archive a note (moves it off the active board; recoverable). */
  async archiveThought(id: string): Promise<{ success: boolean; error?: string }> {
    return this.post(`/api/thoughts/${encodeURIComponent(id)}/archive`, {});
  }

  /** Create a thought group, optionally seeding it with member note ids. */
  async createThoughtGroup(body: { title?: string; memberIds?: string[] }): Promise<{ success: boolean; group?: ThoughtGroup; error?: string }> {
    return this.post("/api/thought-groups", body);
  }

  // ═══════════════════════════════════════════════════════════════════
  // STORIES / TASKS (for leader tools)
  // ═══════════════════════════════════════════════════════════════════

  /**
   * Create a new story on the kanban board.
   *
   * Optionally include inline tasks to create them in the same request.
   */
  async createStory(story: {
    id: string;
    title: string;
    description: string;
    dependsOn?: string[];
    /** Where the work happens — story data; teammates cd here (directory affinity). */
    directory?: string;
    /** Create the story pending: nothing is handed out until it is activated. */
    pending?: boolean;
    workflow?: string;
    tasks?: Array<{ title: string; description: string }>;
  }): Promise<CreateStoryResponse> {
    return this.post<CreateStoryResponse>("/api/stories", story);
  }

  /**
   * Update an existing story's fields.
   *
   * Only the provided fields are changed. Set fields to null to clear them.
   */
  async updateStory(storyId: string, updates: Record<string, any>): Promise<{ success: boolean; error?: string }> {
    const res = await this.request(`/api/stories/${encodeURIComponent(storyId)}`, {
      method: "PUT",
      body: JSON.stringify(updates),
    });
    return res.json() as Promise<{ success: boolean; error?: string }>;
  }

  /**
   * Add a task to an existing story.
   *
   * Tasks are sequential within a story — the daemon assigns the next
   * sequence number automatically. `pending` creates it as pending: it holds
   * its place in the story and gets no WorkItem until activated. (A board task
   * gets its persona from its workflow state, so there's none to pass here.)
   */
  async createTask(storyId: string, title: string, description: string, pending?: boolean): Promise<CreateTaskResponse> {
    return this.post<CreateTaskResponse>(
      `/api/stories/${encodeURIComponent(storyId)}/tasks`,
      { title, description, pending }
    );
  }

  /**
   * List the team's workflows (name, state/transition counts, and which is the
   * default). Lets a planner pick a valid workflow for a story.
   */
  async listWorkflows(): Promise<WorkflowSummary[]> {
    return this.get<WorkflowSummary[]>("/api/workflows");
  }

  /**
   * List the team's persona library (team, built-in, and package personas) so
   * the leader can pick one for a standalone task or a schedule. `kind` sorts
   * the personas hinted for it first.
   */
  async listPersonas(kind?: "assistant" | "teammate" | "triage"): Promise<{ personas: PersonaSummary[] }> {
    return this.get<{ personas: PersonaSummary[] }>(`/api/personas${kind ? `?kind=${kind}` : ""}`);
  }

  // ═══════════════════════════════════════════════════════════════════
  // CONFIG
  // ═══════════════════════════════════════════════════════════════════

  /**
   * Get the daemon's current configuration.
   *
   * Returns port, tmuxSession, defaultWorkflow, etc.
   */
  async getConfig(): Promise<any> {
    return this.get<any>("/api/config");
  }

}
